import subprocess, os, sys, time, signal

def run(args, input_data=None, timeout=3, env=None):
    e=dict(os.environ)
    if env: e.update(env)
    try:
        p=subprocess.run(["./executable"]+args, input=input_data, capture_output=True, timeout=timeout, env=e)
        return p.returncode, p.stdout, p.stderr
    except subprocess.TimeoutExpired as ex:
        return None, ex.stdout or b'', ex.stderr or b''

for args in [[], ["-h"], ["-help"], ["--help"], ["-unknown"], ["-rows"], ["-steps","abc","x"], ["-interval","xyz","x"]]:
    rc,out,err=run(args)
    print(f"args={args} rc={rc}")
    print(" stdout:", repr(out[:2000]))
    print(" stderr:", repr(err[:2000]))
    print()
