import os, pty, subprocess, time, select, fcntl, termios, struct

def run_mixed(args, env_extra=None, stdin_mode='pipe', stdout_mode='pty', stderr_mode='pty', inputs_pty=None, inputs_pipe=None, wait=3, winsize=(24,80,0,0), use_ctty=False):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", *winsize))
    env=dict(os.environ); env.pop("TERM_PROGRAM",None)
    if env_extra:
        for k,v in env_extra.items():
            if v is None: env.pop(k,None)
            else: env[k]=v
    stdin = slave if stdin_mode=='pty' else subprocess.PIPE
    stdout = slave if stdout_mode=='pty' else subprocess.PIPE
    stderr = slave if stderr_mode=='pty' else subprocess.PIPE
    # For ctty, need preexec setsid and ioctl
    def preexec():
        os.setsid()
        fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
    p=subprocess.Popen(["./executable"]+args, stdin=stdin, stdout=stdout, stderr=stderr, env=env, close_fds=True, preexec_fn=preexec if use_ctty else None)
    if stdout_mode=='pty' or stdin_mode=='pty':
        # keep slave? if ctty etc child duped, close in parent after spawn
        pass
    os.close(slave)
    flags=fcntl.fcntl(master, fcntl.F_GETFL); fcntl.fcntl(master, fcntl.F_SETFL, flags|os.O_NONBLOCK)
    out_pty=b""; start=time.time(); idx=0; idxp=0
    inputs_pty=inputs_pty or []; inputs_pipe=inputs_pipe or []
    while time.time()-start < wait:
        while idx < len(inputs_pty) and inputs_pty[idx][0] <= time.time()-start:
            try: os.write(master, inputs_pty[idx][1])
            except Exception as e: print("pty write err",e)
            idx+=1
        while idxp < len(inputs_pipe) and inputs_pipe[idxp][0] <= time.time()-start:
            try:
                p.stdin.write(inputs_pipe[idxp][1]); p.stdin.flush()
            except Exception as e: print("pipe write err",e)
            idxp+=1
        r,_,_=select.select([master],[],[],0.05)
        if master in r:
            try:
                d=os.read(master,65536)
                if d: out_pty+=d
            except: pass
        if p.poll() is not None:
            try:
                while True:
                    d=os.read(master,65536)
                    if not d: break
                    out_pty+=d
            except: pass
            break
    rc=p.poll()
    extra_out=b""; extra_err=b""
    if rc is None:
        p.kill(); 
        try: p.wait(timeout=1)
        except: pass
        rc="running"
    else:
        if stdout_mode!='pty' and p.stdout: extra_out=p.stdout.read() or b""
        if stderr_mode!='pty' and p.stderr: extra_err=p.stderr.read() or b""
    try: os.close(master)
    except: pass
    return rc, out_pty, extra_out, extra_err

for desc,kwargs in [
 ("stdin pipe, stdout pty, stderr pipe separate", dict(args=["a"], stdin_mode='pipe', stdout_mode='pty', stderr_mode='pipe', inputs_pipe=[(0.2,b'{"a":1}\n')], wait=2)),
 ("stdin pipe, stdout pty, ctty", dict(args=["a"], stdin_mode='pipe', stdout_mode='pty', stderr_mode='pty', use_ctty=True, inputs_pipe=[(0.2,b'{"a":1}\n')], inputs_pty=[(0.3,b'\x1b_Gi=1;OK\x1b\\'),(0.4,b'\x1b[?62;4c')], wait=2)),
 ("stdin pty stdout pty (ctty), kitty ok", dict(args=["a"], stdin_mode='pty', stdout_mode='pty', stderr_mode='pty', use_ctty=True, inputs_pty=[(0.3,b'\x1b_Gi=1;OK\x1b\\')], wait=2)),
 ("stdin pty stdout pty, DA sixel", dict(args=["a"], stdin_mode='pty', stdout_mode='pty', stderr_mode='pty', inputs_pty=[(0.3,b'\x1b[?62;4c')], wait=2)),
 ("stdin pipe stdout pty iTerm env", dict(args=["a"], stdin_mode='pipe', stdout_mode='pty', stderr_mode='pipe', env_extra={"TERM_PROGRAM":"iTerm.app"}, inputs_pipe=[(0.2,b'{"a":10}\n'),(0.6,b'{"a":20}\n')], wait=2)),
]:
    rc, out, eout, eerr = run_mixed(**kwargs)
