import os, pty, subprocess, time, select, fcntl, termios, struct, sys, json

def run(args, env_extra=None, responder='kitty', json_inputs=None, wait=4, winsize=(80,24,0,0), stdin_mode='pipe', use_ctty=True, close_stdin_after=None):
    # winsize as (cols,rows,xpix,ypix) for convenience
    cols,rows,xpix,ypix = winsize
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, xpix, ypix))
    env=dict(os.environ); env.pop("TERM_PROGRAM",None); env.pop("KITTY_WINDOW_ID",None)
    if env_extra:
        for k,v in env_extra.items():
            if v is None: env.pop(k,None)
            else: env[k]=v
    def preexec():
        os.setsid()
        fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
        # close master in child
        try: os.close(master)
        except: pass
    stdin = slave if stdin_mode=='pty' else subprocess.PIPE
    p=subprocess.Popen(["./executable"]+args, stdin=stdin, stdout=slave, stderr=slave, env=env, close_fds=True, preexec_fn=preexec if use_ctty else None)
    os.close(slave)
    flags=fcntl.fcntl(master, fcntl.F_GETFL); fcntl.fcntl(master, fcntl.F_SETFL, flags|os.O_NONBLOCK)
    out=b""; log=[]
    start=time.time()
    json_inputs=list(json_inputs or [])  # list of (t, bytes)
    answered=set()
    counts={}
    def send_pty(data, why):
        log.append((time.time()-start, 'SEND_PTY '+why, data))
        try: os.write(master, data)
        except Exception as e: log.append((time.time()-start,'ERR',str(e).encode()))
    def maybe_respond(newdata):
        # we respond based on cumulative out searching queries each time, counting occurrences
        nonlocal out
        # kitty query
        for q, name in [(b'\x1b_Gi=1,a=q,t=d,f=24\x1b\\','kittyq'), (b'\x1b[c','da'), (b'\x1b[14t','14t'), (b'\x1b[16t','16t'), (b'\x1b[18t','18t'), (b'\x1b]1337;ReportCellSize\x07','cellsize'), (b'\x1b[?25l','hide')]:
            c=out.count(q)
            if c>counts.get(name,0):
                counts[name]=c
                # respond
                if name=='kittyq':
                    if responder=='kitty':
                        send_pty(b'\x1b_Gi=1;OK\x1b\\', 'kitty OK')
                    elif responder=='sixel':
                        pass # wait DA
                    elif responder=='none':
                        pass
                elif name=='da':
                    if responder=='kitty':
                        send_pty(b'\x1b[?62;4c','DA reply (kitty mode?)')
                    elif responder=='sixel':
                        send_pty(b'\x1b[?62;4c','DA sixel')
                    elif responder=='sixel_no4':
                        send_pty(b'\x1b[?62c','DA non-sixel')
                    elif responder=='none':
                        send_pty(b'\x1b[?1;2c','DA plain')
                    elif responder=='iterm':
                        pass
                elif name=='14t':
                    # text area pixel size: height,width  rows*? cells
                    h=rows*20; w=cols*10
                    send_pty(f'\x1b[4;{h};{w}t'.encode(), '14t reply')
                elif name=='16t':
                    send_pty(b'\x1b[6;20;10t','16t reply')
                elif name=='18t':
                    send_pty(f'\x1b[8;{rows};{cols}t'.encode(),'18t')
                elif name=='cellsize':
                    send_pty(b'\x1b]1337;ReportCellSize=20.000000;10.000000;1.000000\x07','cellsize reply')
    while time.time()-start < wait:
        # json inputs by time
        while json_inputs and json_inputs[0][0] <= time.time()-start:
            t,data=json_inputs.pop(0)
            log.append((time.time()-start,'SEND_PIPE',data))
            if stdin_mode=='pipe':
                try: p.stdin.write(data); p.stdin.flush()
                except Exception as e: log.append((time.time()-start,'PIPEERR',str(e).encode()))
            else:
                send_pty(data,'json via pty')
        r,_,_=select.select([master],[],[],0.02)
        if master in r:
            try:
                d=os.read(master,65536)
                if d:
                    out+=d; log.append((time.time()-start,'RECV',d)); maybe_respond(d)
                else:
                    pass
            except OSError:
                pass
        if p.poll() is not None:
            # drain
            for _ in range(10):
                try:
                    d=os.read(master,65536)
                    if d: out+=d; log.append((time.time()-start,'RECV',d))
                except: break
            break
    rc=p.poll()
    if rc is None:
        p.kill()
        try: p.wait(timeout=1)
        except: pass
        rc='running'
    try: os.close(master)
    except: pass
    return rc,out,log

def show(rc,out,log, title=''):
    print(f"=== {title} rc={rc} total_len={len(out)} ===")
    for t,kind,data in log:
        print(f"{t:6.3f} {kind:12} {data!r}")
    print()

if __name__=='__main__':
    # smoke
    rc,out,log=run(["a"], responder='kitty', json_inputs=[(1.0,b'{"a":10}\n'),(1.5,b'{"a":20}\n')], wait=3)
    show(rc,out,log,'kitty default')
