import re, sys, base64, os
data=open(sys.argv[1],'rb').read()
print("len",len(data))
i=0; idx=0
outdir=sys.argv[2] if len(sys.argv)>2 else "/tmp/imgs"
os.makedirs(outdir,exist_ok=True)
while i < len(data):
    if data[i:i+3]==b'\x1b_G':
        end=data.find(b'\x1b\\', i)
        if end==-1: print("unterminated G", data[i:i+200]); break
        body=data[i+3:end]
        if b';' in body:
            hdr,payload=body.split(b';',1)
        else:
            hdr,payload=body,b''
        print(f"[{i}] KITTY hdr={hdr!r} payload_len={len(payload)} payload_start={payload[:60]!r}")
        if payload:
            try:
                raw=base64.b64decode(payload)
                fn=f"{outdir}/kitty{idx}.bin"; open(fn,'wb').write(raw); print("  decoded",len(raw),raw[:30], "->",fn)
            except Exception as e: print(" b64 err",e)
            idx+=1
        i=end+2
    elif data[i:i+3]==b'\x1bPq' or data[i]==0x90 or data[i:i+2]==b'\x1bP':
        end=data.find(b'\x1b\\', i)
        if end==-1: print("unterminated DCS",data[i:i+200]); break
        body=data[i:end]
        print(f"[{i}] DCS len={len(body)} start={body[:120]!r} end={body[-50:]!r}")
        fn=f"{outdir}/sixel{idx}.bin"; open(fn,'wb').write(body)
        idx+=1
        i=end+2
    elif data[i:i+2]==b'\x1b]':
        end=data.find(b'\x07', i)
        end2=data.find(b'\x1b\\', i)
        cands=[x for x in [end,end2] if x!=-1]
        if not cands: print("unterminated OSC",data[i:i+200]); break
        end=min(cands)
        term=data[end:end+2]
        body=data[i:end]
        # split payload if File=
        print(f"[{i}] OSC len={len(body)} start={body[:200]!r} term={term!r}")
        if b':' in body or b';' in body:
            # try extract base64 after last ; or :
            # iTerm format: ESC ]1337;File=...:base64 BEL
            m=re.search(rb':([A-Za-z0-9+/=]+)$', body)
            if m and len(m.group(1))>50:
                try:
                    raw=base64.b64decode(m.group(1)); fn=f"{outdir}/iterm{idx}.bin"; open(fn,'wb').write(raw); print("  decoded payload",len(raw),raw[:20],fn)
                except Exception as e: print(e)
                idx+=1
        i=end+(1 if term==b'\x07' else 2)
    elif data[i]==0x1b:
        m=re.match(rb'\x1b\[[0-9;?]*[A-Za-z@`~]|\x1b[()][0-9A-B]|\x1b.', data[i:])
        if m:
            print(f"[{i}] ESC {m.group(0)!r}"); i+=len(m.group(0))
        else:
            print(f"[{i}] ESC lone"); i+=1
    elif data[i] in b'\r\n':
        j=i
        while j<len(data) and data[j] in b'\r\n': j+=1
        print(f"[{i}] CRLF x{j-i} {data[i:j]!r}"); i=j
    else:
        j=i
        while j<len(data) and data[j]!=0x1b: j+=1
        print(f"[{i}] TEXT {data[i:j]!r}"); i=j
