import subprocess, os, time, select
def run_pipe(args, env_extra=None, sends=None, wait=4):
    env=dict(os.environ); env.pop("TERM_PROGRAM",None)
    if env_extra: env.update(env_extra)
    p=subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    out=b""; err=b""; start=time.time(); sends=list(sends or [])
    # nonblock
    import fcntl
    for f in [p.stdout,p.stderr]:
        fl=fcntl.fcntl(f, fcntl.F_GETFL); fcntl.fcntl(f, fcntl.F_SETFL, fl|os.O_NONBLOCK)
    log=[]
    while time.time()-start<wait:
        while sends and sends[0][0]<=time.time()-start:
            t,d=sends.pop(0); log.append((time.time()-start,'SEND',d))
            try: p.stdin.write(d); p.stdin.flush()
            except Exception as e: log.append((time.time()-start,'ERR',str(e).encode()))
        r,_,_=select.select([p.stdout,p.stderr],[],[],0.02)
        for f in r:
            try:
                d=os.read(f.fileno(),65536)
                if d: log.append((time.time()-start, 'OUT' if f==p.stdout else 'ERR', d))
            except: pass
        if p.poll() is not None: break
    rc=p.poll()
    if rc is None:
        p.kill(); p.wait(); rc='running'
    return rc,log

for name,kwargs in [
 ("pipe no send open stdin", dict(args=["a"], sends=[], wait=3)),
 ("pipe DA resp", dict(args=["a"], sends=[(0.3,b'\x1b[?62;4c'),(0.6,b'{"a":1}\n')], wait=3)),
 ("pipe kitty resp", dict(args=["a"], sends=[(0.3,b'\x1b_Gi=1;OK\x1b\\'),(0.6,b'\x1b[?62;4c'),(0.8,b'{"a":1}\n')], wait=3)),
 ("pipe kitty then DA no4", dict(args=["a"], sends=[(0.3,b'\x1b_Gi=1;OK\x1b\\'),(0.6,b'\x1b[?62c')], wait=2)),
 ("pipe close-ish JSON", dict(args=["a"], sends=[(0.3,b'{"a":1}\n')], wait=2)),
]:
    rc,log=run_pipe(**kwargs)
    print(name, rc)
    for t,k,d in log: print(f" {t:.3f} {k} {d[:250]!r}")
    print()
