import os, pty, subprocess, time, select, fcntl, termios, struct
class Harness:
    def __init__(self, args, env_extra=None, winsize=(40,10,0,0), responder='kitty'):
        cols,rows,xp,yp=winsize
        self.cols=cols; self.rows=rows
        self.master,self.slave=pty.openpty()
        fcntl.ioctl(self.slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows,cols,xp,yp))
        env=dict(os.environ); env.pop("TERM_PROGRAM",None)
        if env_extra:
            for k,v in env_extra.items():
                if v is None: env.pop(k,None)
                else: env[k]=v
        self.responder=responder
        def preexec():
            os.setsid(); fcntl.ioctl(self.slave, termios.TIOCSCTTY,0)
        self.p=subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=self.slave, stderr=subprocess.PIPE, env=env, pass_fds=(self.slave,), preexec_fn=preexec)
        os.close(self.slave)
        for fd in [self.master, self.p.stderr.fileno()]:
            fl=fcntl.fcntl(fd, fcntl.F_GETFL); fcntl.fcntl(fd, fcntl.F_SETFL, fl|os.O_NONBLOCK)
        self.start=time.time(); self.out=b''; self.err=b''; self.log=[]; self.counts={}
    def elapsed(self): return time.time()-self.start
    def send_pty(self,d,why=''):
        self.log.append((self.elapsed(),'PTY_SEND '+why,d)); os.write(self.master,d)
    def send_stdin(self,d):
        self.log.append((self.elapsed(),'STDIN_SEND',d)); self.p.stdin.write(d); self.p.stdin.flush()
    def close_stdin(self):
        self.log.append((self.elapsed(),'STDIN_CLOSE',b'')); 
        try: self.p.stdin.close()
        except Exception as e: pass
    def respond(self):
        data=self.out
        checks=[
          (b'\x1b_Gi=1,a=q,t=d,f=24\x1b\\','kittyq'),
          (b'\x1b[c','da'),
          (b'\x1b[14t','14t'),
          (b'\x1b[16t','16t'),
          (b'\x1b[18t','18t'),
          (b'\x1b]1337;ReportCellSize\x07','cell'),
        ]
        for q,name in checks:
            c=data.count(q)
            if c>self.counts.get(name,0):
                self.counts[name]=c
                if name=='kittyq':
                    if self.responder=='kitty': self.send_pty(b'\x1b_Gi=1;OK\x1b\\','kittyok')
                    elif self.responder=='sixel': self.send_pty(b'\x1b[?62c','da-plain-kittyresp')
                    elif self.responder=='none': self.send_pty(b'\x1b[?62c','da-plain-kittyresp')
                    elif self.responder=='iterm': pass
                    else:
                        # custom raw response stored
                        if isinstance(self.responder,tuple): self.send_pty(self.responder[0],'kittyresp')
                elif name=='da':
                    if self.responder in ('kitty','none'): self.send_pty(b'\x1b[?62c','da-plain')
                    elif self.responder=='sixel': self.send_pty(b'\x1b[?62;4;6c','da-sixel')
                    elif isinstance(self.responder,tuple): self.send_pty(self.responder[1],'da')
                elif name=='14t': self.send_pty(f'\x1b[4;{self.rows*20};{self.cols*10}t'.encode(),'14t')
                elif name=='16t': self.send_pty(b'\x1b[6;20;10t','16t')
                elif name=='18t': self.send_pty(f'\x1b[8;{self.rows};{self.cols}t'.encode(),'18t')
                elif name=='cell': self.send_pty(b'\x1b]1337;ReportCellSize=20.000000;10.000000;1.000000\x07','cell')
    def run_for(self,dur, actions=None):
        # actions list (t, callable)
        actions=list(actions or []); end=self.elapsed()+dur
        while self.elapsed()<end:
            while actions and actions[0][0]<=self.elapsed():
                t,fn=actions.pop(0); fn(self)
            r,_,_=select.select([self.master,self.p.stderr],[],[],0.005)
            for f in r:
                try: d=os.read(f.fileno() if hasattr(f,'fileno') else f,65536)
                except: d=b''
                if not d: continue
                if f==self.master: self.out+=d; self.log.append((self.elapsed(),'OUT',d)); self.respond()
                else: self.err+=d; self.log.append((self.elapsed(),'ERR',d))
            if self.p.poll() is not None:
                # drain
                for _ in range(20):
                    r,_,_=select.select([self.master,self.p.stderr],[],[],0.01)
                    if not r: break
                    for f in r:
                        try: d=os.read(f.fileno() if hasattr(f,'fileno') else f,65536)
                        except: d=b''
                        if d:
                            if f==self.master: self.out+=d; self.log.append((self.elapsed(),'OUT',d))
                            else: self.err+=d; self.log.append((self.elapsed(),'ERR',d))
                break
        return self.p.poll()
    def kill(self):
        if self.p.poll() is None: self.p.kill(); self.p.wait()
    def show(self,title='',maxlen=220):
        rc=self.p.poll(); print(f"=== {title} rc={rc} outlen={len(self.out)} errlen={len(self.err)}")
        for t,k,d in self.log:
            ds=d if len(d)<=maxlen else d[:maxlen]+b'...'
            print(f"{t:.3f} {k:18} len={len(d)} {ds!r}")
        print()
