import re, sys
def decode_sixel(data):
    # data DCS contents starting after q? accept full sequence
    start=data.find(b'q')
    s=data[start+1:]
    if s.endswith(b'\x1b\\'): s=s[:-2]
    i=0; colors={}; cur=0; x=0; y=0; maxx=0; pixels={}
    # parse
    def read_int(s,i):
        j=i; 
        while j<len(s) and 48<=s[j]<=57: j+=1
        return (int(s[i:j]) if j>i else 0,j)
    while i<len(s):
        c=s[i:i+1]
        if c==b'"':
            # raster attributes until one of #!? etc: numbers/semicolons
            i+=1
            while i<len(s) and (48<=s[i]<=57 or s[i]==59): i+=1
        elif c==b'#':
            i+=1; pc,i=read_int(s,i)
            if i<len(s) and s[i]==59: # ;
                # color definition ;2;r;g;b
                vals=[]; 
                while i<len(s) and s[i]==59:
                    i+=1; v,i=read_int(s,i); vals.append(v)
                if len(vals)>=4 and vals[0]==2: colors[pc]=tuple(round(v*255/100) for v in vals[1:4])
                elif len(vals)>=4 and vals[0]==1: colors[pc]=('hls',vals[1:4])
                cur=pc
            else:
                cur=pc
        elif c==b'!':
            i+=1; n,i=read_int(s,i); 
            if i<len(s):
                ch=s[i]; i+=1; bits=ch-63
                for rep in range(n):
                    for b in range(6):
                        if bits>>b &1: pixels[(x,y+b)]=cur
                    x+=1; maxx=max(maxx,x)
        elif c==b'$': x=0; i+=1
        elif c==b'-': x=0; y+=6; i+=1
        elif 63<=s[i]<=126:
            bits=s[i]-63; i+=1
            for b in range(6):
                if bits>>b &1: pixels[(x,y+b)]=cur
            x+=1; maxx=max(maxx,x)
        else:
            i+=1
    h=y+6 if pixels else 0
    return colors,pixels,maxx,h
if __name__=='__main__':
    data=open(sys.argv[1],'rb').read()
    # extract DCS sequences
    seqs=re.findall(rb'\x1bP.*?\x1b\\',data,re.S)
    print('seqs',len(seqs))
    for idx,s in enumerate(seqs):
        colors,pix,w,h=decode_sixel(s); print(idx,'w',w,'h',h,'colors',len(colors),'pixels',len(pix))
        print(' first colors',list(sorted(colors.items()))[:20])
        # colors used
        from collections import Counter
        print(' used colors counts',Counter(pix.values()).most_common(20))
        # save PPM-ish? write a binary raw description for Go compare later
        with open(f'/tmp/sixel_decoded_{idx}.txt','w') as f:
            f.write(f'{w} {h}\n')
            for (x,y),pc in sorted(pix.items()): f.write(f'{x} {y} {colors.get(pc)}\n')
