import subprocess,sys
def segments(fn,x,y,w,h,mode=0):
    out=subprocess.check_output(["go","run","/tmp/segments.go",fn,str(x),str(y),str(w),str(h),str(mode)],text=True)
    segs=[]; cur=None
    for line in out.splitlines():
        if line.startswith('SEG '):
            if cur: segs.append(cur)
            _,sx,sw=line.split(); cur={'x':int(sx),'w':int(sw),'rows':[]}
        elif cur is not None:
            cur['rows'].append(line.rstrip())
    if cur: segs.append(cur)
    # normalize rows to segment width
    for s in segs:
        s['rows']=[r.ljust(s['w'])[:s['w']] for r in s['rows']]
    return segs

def bitmap(seg):
    return tuple(seg['rows'])
# Train on static bottom labels
static='/tmp/imgs_static0/kitty0.bin'
segs=segments(static,0,444,760,11,0)
# group by gaps >12
groups=[]; cur=[]; last=None
for s in segs:
    if last is not None and s['x']-last>12:
        groups.append(cur);cur=[]
    cur.append(s);last=s['x']+s['w']
if cur:groups.append(cur)
expected=['0.00','0.75','1.50','2.25','3.00','3.75','4.50','5.25','6.00','6.75','7.50','8.25','9.00']
print('groups',len(groups),[len(g) for g in groups])
templates={}
for g,exp in zip(groups,expected):
    if len(g)!=len(exp): print('mismatch',exp,len(g),[s['x'] for s in g]); continue
    for s,ch in zip(g,exp): templates.setdefault(ch,[]).append(bitmap(s))

def dist(a,b):
    # a,b tuples rows maybe diff h align bottom, diff w align left; count mismatches padded
    ha,hb=len(a),len(b); h=max(ha,hb); wa=len(a[0]) if a else 0; wb=len(b[0]) if b else 0; w=max(wa,wb)
    d=0
    for yy in range(h):
        ra=a[yy-(h-ha)] if yy>=(h-ha) else ''
        rb=b[yy-(h-hb)] if yy>=(h-hb) else ''
        for xx in range(w):
            ca=ra[xx] if xx<len(ra) else ' '; cb=rb[xx] if xx<len(rb) else ' '
            if ca!=cb:d+=1
    return d

def ocr_seg(seg):
    b=bitmap(seg); best=[]
    for ch,tlist in templates.items():
        d=min(dist(b,t) for t in tlist); best.append((d,ch))
    best.sort(); return best[:3]

def ocr_region(fn,x,y,w,h,mode=0):
    ss=segments(fn,x,y,w,h,mode); out=''
    last=None
    for s in ss:
