		return modeSixel
	}
	if kitty {
		return modeKitty
	}
	return modeNone
}

func ioctl(fd uintptr, req uintptr, arg unsafe.Pointer) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, req, uintptr(arg))
	if errno != 0 {
		return errno
	}
	return nil
}

func tcGetAttr(fd uintptr) (*syscall.Termios, error) {
	var t syscall.Termios
	if err := ioctl(fd, syscall.TCGETS, unsafe.Pointer(&t)); err != nil {
		return nil, err
	}
	return &t, nil
}

func tcSetAttr(fd uintptr, t *syscall.Termios) error {
	return ioctl(fd, syscall.TCSETS, unsafe.Pointer(t))
}

func isTerminal(fd uintptr) bool {
	_, err := tcGetAttr(fd)
	return err == nil
}

func makeRaw(fd uintptr) (*syscall.Termios, error) {
	old, err := tcGetAttr(fd)
	if err != nil {
		return nil, err
	}
	raw := *old
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP |
		syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if err := tcSetAttr(fd, &raw); err != nil {
		return nil, err
	}
	return old, nil
}

func probeKitty() bool {
	fd := os.Stdout.Fd()
	old, err := makeRaw(fd)
	if err != nil {
		return false
	}
	defer tcSetAttr(fd, old)
	_, _ = os.Stdout.WriteString("\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
	buf := make([]byte, 200)
	n, _ := os.Stdout.Read(buf)
	if n <= 0 {
		return false
	}
	return bytes.Contains(buf[:n], []byte("_Gi=1"))
}

func sixelDAIsSupported(resp string) bool {
	parts := strings.Split(resp, ";")
	if len(parts) < 2 {
		return false
	}
	switch parts[0] {
	case "\x1b[?62", "\x1b[?63", "\x1b[?64", "\x1b[?65":
	default:
		return false
	}
	for _, p := range parts[1:] {
		if p == "4" {
			return true
		}
	}
	return false
}

func probeSixel() bool {
	// The DA query is emitted even when stdout is not a terminal;
	// only afterwards does the probe try to switch to raw mode.
	_, _ = os.Stdout.WriteString("\x1b[c")
	fd := os.Stdout.Fd()
	old, err := makeRaw(fd)
	if err != nil {
		return false
	}
	defer tcSetAttr(fd, old)
	buf := make([]byte, 100)
	n, _ := os.Stdout.Read(buf)
	if n <= 0 {
		return false
	}
	return sixelDAIsSupported(string(buf[:n]))
}

type winsize struct {
	Row    uint16
	Col    uint16
	XPix   uint16
	YPix   uint16
}

func getWindowSize() (cols, rows int, err error) {
	var ws winsize
	if err := ioctl(os.Stdout.Fd(), syscall.TIOCGWINSZ, unsafe.Pointer(&ws)); err != nil {
		return 0, 0, err
	}
	return int(ws.Col), int(ws.Row), nil
}

var errCellSize = errors.New("cannot get terminal cell size")

// queryTerminalCellSize returns, depending on mode:
//  - iTerm: cell width/height in pixels (cw, ch)
//  - Kitty/Sixel: total terminal pixel width/height (pw, ph)
//
// It must only be called once (result is cached by caller).
func (rs *renderState) queryTerminalCellSize() error {
	fd := os.Stdout.Fd()
	old, err := makeRaw(fd)
	if err != nil {
		return errCellSize
	}
	defer tcSetAttr(fd, old)

	if rs.mode == modeITerm {
		_, _ = os.Stdout.WriteString("\x1b]1337;ReportCellSize\x07")
		var h, w float64
		// The reference ignores the scan error except for the
		// both-zero case (partial scans leak a zero dimension
		// through to the PNG encoder).
		_, _ = fmt.Fscanf(os.Stdout, "\x1b]1337;ReportCellSize=%v;%v", &h, &w)
		if h == 0 && w == 0 {
			return errCellSize
		}
		rs.cellW = int(w)
		rs.cellH = int(h)
		return nil
	}
	_, _ = os.Stdout.WriteString("\x1b[14t")
	var ph, pw int
	if _, err := fmt.Fscanf(os.Stdout, "\x1b[4;%d;%d", &ph, &pw); err != nil || ph <= 0 || pw <= 0 {
		return errCellSize
	}
	rs.pixW = pw
	rs.pixH = ph
	return nil
}
