		}
	}
	return toks
}

func getPathValue(data interface{}, path string) (float64, error) {
	cur := data
	for _, key := range pathTokens(path) {
		m, ok := cur.(map[string]interface{})
		if !ok {
			return 0, fmt.Errorf("cannot get %s: %s is not an object. %v", path, key, m)
