	resp.Body.Close()
	if err != nil {
		return nil, fmt.Errorf("input error: %w", err)
	}
	var v interface{}
	if err := json.Unmarshal(body, &v); err != nil {
		return nil, fmt.Errorf("input error: %w", err)
	}
	return v, nil
}

func (s *httpSource) run(ctx context.Context, url string, interval time.Duration) {
	defer close(s.ch)
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		v, err := fetchHTTP(url)
		select {
		case s.ch <- httpResult{data: v, err: err}:
		case <-ctx.Done():
			return
		}
		if err != nil {
			return
		}
		select {
		case <-ticker.C:
		case <-ctx.Done():
			return
		}
	}
}

func (s *httpSource) Get(ctx context.Context) (interface{}, error) {
	res, ok := <-s.ch
	if !ok {
		return nil, io.EOF
	}
	if res.err != nil {
		return nil, res.err
	}
	return res.data, nil
}

