type points struct {
	mu     sync.Mutex
	graphs [][]*fieldSpec
	steps  int

	// For steps > 0, histories[f] always has length steps.
	// For steps <= 0 we keep an appending slice; rendering will
	// panic the same way the reference does when it tries to
	// build a slice of length steps.
	histories map[*fieldSpec][]float64
}

func newPoints(graphs [][]*fieldSpec, steps int) *points {
	p := &points{graphs: graphs, steps: steps, histories: make(map[*fieldSpec][]float64)}
	for _, g := range graphs {
		for _, f := range g {
			if steps > 0 {
				p.histories[f] = make([]float64, steps)
			} else {
				p.histories[f] = nil
			}
		}
	}
	return p
