func (p *points) appendValue(f *fieldSpec, v float64) {
	h := p.histories[f]
	if p.steps > 0 {
		copy(h, h[1:])
		h[len(h)-1] = v
		p.histories[f] = h
	} else {
		p.histories[f] = append(h, v)
	}
