	first := true
	for {
		obj, err := src.Get(ctx)
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return err
		}

		p.mu.Lock()
		for _, group := range p.graphs {
			for _, f := range group {
				v, err := getPathValue(obj, f.Path)
				if err != nil {
					p.mu.Unlock()
					return err
