// zero-padded on the left. For steps < 0 the make() panics (as in
// the reference); for steps == 0 an empty slice is returned and
// callers indexing the last element will panic.
func (p *points) getHistory(f *fieldSpec) []float64 {
	p.mu.Lock()
	defer p.mu.Unlock()
	out := make([]float64, p.steps)
	h := p.histories[f]
	if p.steps > 0 {
		copy(out, h)
	}
	return out
