type snapshot struct {
	graphs [][][]float64 // [graph][field][step]
	// fields mirrors specs so the renderer can check Marker etc.
	specs [][]*fieldSpec
}

func (p *points) snapshot() snapshot {
	snap := snapshot{specs: p.graphs}
	for _, g := range p.graphs {
		var gf [][]float64
		for _, f := range g {
			gf = append(gf, p.getHistory(f))
		}
		snap.graphs = append(snap.graphs, gf)
	}
	return snap
}
