		return nil, fmt.Errorf("input error: %w", err)
	}
	return v, nil
}

func (s *httpSource) run(ctx context.Context, url string, interval time.Duration) {
	defer close(s.ch)
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		v, err := fetchHTTP(url)
		select {
		case s.ch <- httpResult{data: v, err: err}:
		case <-ctx.Done():
			return
		}
		if err != nil {
			return
		}
		select {
		case <-ticker.C:
		case <-ctx.Done():
			return
		}
	}
}

func (s *httpSource) Get(ctx context.Context) (interface{}, error) {
	res, ok := <-s.ch
	if !ok {
		return nil, io.EOF
	}
	if res.err != nil {
		return nil, res.err
	}
	return res.data, nil
}

// ---- points ----

type points struct {
	mu     sync.Mutex
	graphs [][]*fieldSpec
	steps  int

	// For steps > 0, histories[f] always has length steps.
	// For steps <= 0 we keep an appending slice; rendering will
	// panic the same way the reference does when it tries to
	// build a slice of length steps.
	histories map[*fieldSpec][]float64
}

func newPoints(graphs [][]*fieldSpec, steps int) *points {
	p := &points{graphs: graphs, steps: steps, histories: make(map[*fieldSpec][]float64)}
	for _, g := range graphs {
		for _, f := range g {
			if steps > 0 {
				p.histories[f] = make([]float64, steps)
			} else {
				p.histories[f] = nil
			}
		}
	}
	return p
}

func (p *points) appendValue(f *fieldSpec, v float64) {
	h := p.histories[f]
	if p.steps > 0 {
		copy(h, h[1:])
		h[len(h)-1] = v
		p.histories[f] = h
	} else {
		p.histories[f] = append(h, v)
	}
}

func (p *points) Run(ctx context.Context, src source) error {
	first := true
	for {
		obj, err := src.Get(ctx)
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return err
		}

		p.mu.Lock()
		for _, group := range p.graphs {
			for _, f := range group {
				v, err := getPathValue(obj, f.Path)
				if err != nil {
					p.mu.Unlock()
					return err
				}
				if f.Counter {
					if f.last == 0 {
						f.last = v
						v = 0
					} else {
						d := v - f.last
						f.last = v
						if d < 0 {
							d = 0
						}
						v = d
					}
				}
				p.appendValue(f, v)
			}
		}
		p.mu.Unlock()

		if first && p.steps <= 0 {
			// The reference finishes (and does its final render)
			// right after the first sample when steps <= 0.
			return nil
		}
		first = false
	}
}

// getHistory returns a copy of exactly steps values for a field,
// zero-padded on the left. For steps < 0 the make() panics (as in
// the reference); for steps == 0 an empty slice is returned and
// callers indexing the last element will panic.
func (p *points) getHistory(f *fieldSpec) []float64 {
	p.mu.Lock()
	defer p.mu.Unlock()
	out := make([]float64, p.steps)
	h := p.histories[f]
	if p.steps > 0 {
		copy(out, h)
	}
	return out
}

// snapshot holds all histories at render time.
type snapshot struct {
	graphs [][][]float64 // [graph][field][step]
	// fields mirrors specs so the renderer can check Marker etc.
	specs [][]*fieldSpec
}

func (p *points) snapshot() snapshot {
	snap := snapshot{specs: p.graphs}
	for _, g := range p.graphs {
		var gf [][]float64
		for _, f := range g {
			gf = append(gf, p.getHistory(f))
		}
		snap.graphs = append(snap.graphs, gf)
	}
	return snap
}
