			if ox > 0 {
				blendPixel(img, x, y, c, ox*oy)
			}
		}
	}
}

func drawLine(img *image.NRGBA, x0, y0, x1, y1, width float64, c color.NRGBA) {
	minx := int(math.Floor(math.Min(x0, x1) - width - 1))
	maxx := int(math.Ceil(math.Max(x0, x1) + width + 1))
	miny := int(math.Floor(math.Min(y0, y1) - width - 1))
	maxy := int(math.Ceil(math.Max(y0, y1) + width + 1))
	dx, dy := x1-x0, y1-y0
	lensq := dx*dx + dy*dy
	half := width / 2
	for y := miny; y <= maxy; y++ {
		for x := minx; x <= maxx; x++ {
			px, py := float64(x)+0.5, float64(y)+0.5
			t := 0.0
			if lensq > 0 {
				t = ((px-x0)*dx + (py-y0)*dy) / lensq
				if t < 0 {
					t = 0
				} else if t > 1 {
					t = 1
				}
			}
			cx, cy := x0+t*dx, y0+t*dy
			dist := math.Hypot(px-cx, py-cy)
			cov := half + 0.5 - dist
			if cov > 0 {
				blendPixel(img, x, y, c, cov)
			}
		}
	}
}

// ---- render state ----

type renderState struct {
	mode     termMode
	pts      *points
	rowsFlag int

	cellReady bool
	cellW     int
	cellH     int
	pixW      int
	pixH      int

	frame   int
	prevKittyID int
}

func fatalMsg(msg string) {
	fmt.Fprintf(os.Stdout, "jplot:  %s\n", msg)
	os.Exit(1)
}

func (rs *renderState) render() {
	cols, termRows, err := getWindowSize()
	if err != nil {
		fatalMsg(fmt.Sprintf("Cannot get window size:  %v", err))
	}
	if !rs.cellReady {
		if err := rs.queryTerminalCellSize(); err != nil {
			fatalMsg(fmt.Sprintf("Cannot get window size:  %v", err))
		}
		rs.cellReady = true
	}

	var fullW, fullH int
	if rs.mode == modeITerm {
		fullW = cols * rs.cellW
		fullH = termRows * rs.cellH
	} else {
		fullW = (cols - 1) * (rs.pixW / (cols - 1))
		fullH = (termRows - 1) * (rs.pixH / (termRows - 1))
	}
	imgW, imgH := fullW, fullH
	if rs.rowsFlag > 0 {
		imgH = rs.rowsFlag * (fullH / termRows)
	}

	snap := rs.pts.snapshot()
	img, err := buildDashboard(snap, imgW, imgH)
	if err != nil {
		fatalMsg(fmt.Sprintf("cannot render graph: %v", err))
	}

	switch rs.mode {
	case modeKitty:
		var buf bytes.Buffer
		if err := png.Encode(&buf, img); err != nil {
			fatalMsg(fmt.Sprintf("cannot render graph: %v", err))
		}
		id := 2 - (rs.frame % 2)
		fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=%d,X=0,Y=0,q=2;%s\x1b\\", id, base64.StdEncoding.EncodeToString(buf.Bytes()))
		if rs.prevKittyID != 0 {
			fmt.Fprintf(os.Stdout, "\x1b_Ga=d,d=i,i=%d,q=2\x1b\\", rs.prevKittyID)
		}
		rs.prevKittyID = id
	case modeITerm:
		var buf bytes.Buffer
		if err := png.Encode(&buf, img); err != nil {
			fatalMsg(fmt.Sprintf("cannot render graph: %v", err))
		}
		fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", imgW, imgH, base64.StdEncoding.EncodeToString(buf.Bytes()))
	case modeSixel:
		if err := encodeSixel(os.Stdout, img); err != nil {
			fatalMsg(fmt.Sprintf("cannot render graph: %v", err))
		}
	}
	rs.frame++
}

var (
	errNoSeries = errors.New("please provide at least one series")
	errZeroX    = errors.New("zero x-range delta; there needs to be at least (2) values")
)

var palette = []color.NRGBA{
	{0, 116, 217, 255},
	{0, 217, 101, 255},
	{217, 0, 116, 255},
	{0, 217, 210, 255},
	{217, 101, 0, 255},
	{106, 195, 203, 255},
	{42, 190, 137, 255},
	{110, 128, 139, 255},
	{240, 174, 90, 255},
}

var (
	axisColor   = color.NRGBA{179, 179, 179, 128}
	textColor   = color.NRGBA{180, 180, 180, 255}
	legendBG    = color.NRGBA{0, 0, 0, 100}
	markerColor = color.NRGBA{110, 128, 139, 100}
	whiteColor  = color.NRGBA{255, 255, 255, 255}
)

type seriesData struct {
	field *fieldSpec
	vals  []float64
	color color.NRGBA
	last  float64
}

func buildDashboard(snap snapshot, imgW, imgH int) (*image.NRGBA, error) {
	// Validate each graph first.
	for gi, specs := range snap.specs {
		hasSeries := false
		for _, f := range specs {
			if f.Marker {
				continue
			}
			hasSeries = true
		}
		if !hasSeries {
			return nil, errNoSeries
		}
		_ = gi
		if len(snap.graphs[gi]) > 0 {
			// Access the last value of the first normal series
			// (panics for steps == 0, like the reference).
			for fi, f := range specs {
				if !f.Marker {
					_ = snap.graphs[gi][fi][len(snap.graphs[gi][fi])-1]
					break
				}
			}
		}
		if pSteps(snap, gi) == 1 {
			return nil, errZeroX
		}
	}

	img := image.NewNRGBA(image.Rect(0, 0, imgW, imgH))
	if imgW <= 0 || imgH <= 0 || len(snap.specs) == 0 {
		return img, nil
	}
	chartH := imgH / len(snap.specs)
	for gi := range snap.specs {
		renderChart(img, gi*chartH, imgW, chartH, snap.specs[gi], snap.graphs[gi])
	}
	return img, nil
}

func pSteps(snap snapshot, gi int) int {
	if len(snap.graphs[gi]) == 0 {
		return 0
	}
	return len(snap.graphs[gi][0])
}

func renderChart(img *image.NRGBA, offY, w, h int, specs []*fieldSpec, hists [][]float64) {
	if w <= 0 || h <= 0 {
		return
	}
	var series []*seriesData
	ymin := math.Inf(1)
	ymax := math.Inf(-1)
	for fi, f := range specs {
		if f.Marker {
			continue
		}
		sd := &seriesData{field: f, vals: hists[fi], color: palette[len(series)%len(palette)]}
		// Palette index is by normal-series order.
		sd.last = sd.vals[len(sd.vals)-1]
		for _, v := range sd.vals {
			if v < ymin {
				ymin = v
			}
			if v > ymax {
				ymax = v
			}
		}
		series = append(series, sd)
	}
	if len(series) == 0 {
		return
	}
	steps := len(series[0].vals)
	if ymin == ymax {
		ymin -= 0.05
		ymax += 0.05
	}

	hasMarker := false
	for fi, f := range specs {
		if f.Marker {
			for _, v := range hists[fi] {
				if v != 0 {
					hasMarker = true
				}
			}
		}
	}

	boxLeft := 12
	boxTop := offY + 10
	boxBottom := offY + h - 27
	if hasMarker {
		boxLeft = 0
		boxBottom = offY + h - 21
	}
	if boxBottom < boxTop+5 {
		boxBottom = boxTop + 5
	}
	plotH := boxBottom - boxTop

	// Y ticks.
	yIntervals := int(float64(plotH) / 36)
	if yIntervals < 1 {
		yIntervals = 1
	}
	yTickCount := yIntervals + 1
	yLabels := make([]string, yTickCount)
	maxYLabelW := 0
	for i := 0; i < yTickCount; i++ {
		v := ymax - (ymax-ymin)*float64(i)/float64(yIntervals)
		yLabels[i] = formatSI(v)
		if mw := measureText(yLabels[i]); mw > maxYLabelW {
			maxYLabelW = mw
		}
	}
	boxRight := w - (maxYLabelW + 22)
	if boxRight < boxLeft+20 {
		boxRight = boxLeft + 20
	}
	plotW := boxRight - boxLeft

	xIntervals := int(float64(plotW) / 60)
	if xIntervals < 1 {
		xIntervals = 1
	}
	xTickCount := xIntervals + 1

	xFor := func(i int) float64 {
		return float64(boxLeft) + float64(plotW)*float64(i)/float64(steps-1)
	}
	yFor := func(v float64) float64 {
		return float64(boxBottom) - (v-ymin)/(ymax-ymin)*float64(plotH)
	}

	// Axes lines: left, right, bottom.
	drawLine(img, float64(boxLeft), float64(boxTop), float64(boxLeft), float64(boxBottom), 2, axisColor)
	drawLine(img, float64(boxRight), float64(boxTop), float64(boxRight), float64(boxBottom), 2, axisColor)
	drawLine(img, float64(boxLeft), float64(boxBottom), float64(boxRight), float64(boxBottom), 2, axisColor)

	// Y tick marks and labels.
	for i := 0; i < yTickCount; i++ {
		ty := float64(boxTop) + float64(plotH)*float64(i)/float64(yIntervals)
		drawLine(img, float64(boxRight+1), ty, float64(boxRight+5), ty, 2, axisColor)
		drawText(img, boxRight+11, int(ty+4), yLabels[i], textColor)
	}
	// X tick marks and labels.
	if !hasMarker {
		for i := 0; i < xTickCount; i++ {
			tx := float64(boxLeft) + float64(plotW)*float64(i)/float64(xIntervals)
			drawLine(img, tx, float64(boxBottom+1), tx, float64(boxBottom+5), 2, axisColor)
			v := float64(steps-1) * float64(i) / float64(xIntervals)
			lab := fmt.Sprintf("%.2f", v)
			drawText(img, int(tx)-measureText(lab)/2, boxBottom+21, lab, textColor)
		}
	}

	// Series fills and lines.
	for _, sd := range series {
		fill := sd.color
		fill.A = 20
		// Fill under the line, column by column.
		x0i := int(math.Ceil(xFor(0)))
		x1i := int(math.Floor(xFor(steps - 1)))
		for x := x0i; x <= x1i; x++ {
			// Interpolate y at x.
			fx := (float64(x) - float64(boxLeft)) / float64(plotW) * float64(steps-1)
			idx := int(math.Floor(fx))
			if idx < 0 {
				idx = 0
			}
			if idx >= steps-1 {
				idx = steps - 2
			}
			frac := fx - float64(idx)
			if frac < 0 {
				frac = 0
			} else if frac > 1 {
				frac = 1
			}
			v := sd.vals[idx]*(1-frac) + sd.vals[idx+1]*frac
			yt := yFor(v)
			top := int(math.Floor(yt))
			for y := top; y < boxBottom; y++ {
				cov := 1.0
				if y == top {
					cov = float64(y+1) - yt
					if cov < 0 {
						cov = 0
					} else if cov > 1 {
						cov = 1
					}
				}
				blendPixel(img, x, y, fill, cov)
			}
		}
		for i := 0; i < steps-1; i++ {
			drawLine(img, xFor(i), yFor(sd.vals[i]), xFor(i+1), yFor(sd.vals[i+1]), 2, sd.color)
		}
	}

	// Marker vertical dashed lines.
	for fi, f := range specs {
		if !f.Marker {
			continue
		}
		for i, v := range hists[fi] {
			if v == 0 {
				continue
			}
			x := xFor(i)
			for y := boxTop; y < boxBottom; y += 4 {
				drawLine(img, x, float64(y), x, math.Min(float64(y+2), float64(boxBottom)), 2, markerColor)
			}
		}
	}

	// Last-value tags.
	for _, sd := range series {
		drawTag(img, xFor(steps-1), yFor(sd.last), formatSI(sd.last), sd.color, w, offY, h)
	}

	// Legend.
	type entry struct {
		text string
		col  color.NRGBA
	}
	var entries []entry
	maxTextW := 0
	for _, sd := range series {
		t := fmt.Sprintf("%s: %s", sd.field.Path, formatSI(sd.last))
		entries = append(entries, entry{t, sd.color})
		if tw := measureText(t); tw > maxTextW {
			maxTextW = tw
		}
	}
	legW := maxTextW + 40
	legH := len(entries)*14 + 12
	legX := boxLeft + 2
	legY := boxTop + 2
	if hasMarker {
		legX = 1
	}
	fillRectF(img, float64(legX), float64(legY), float64(legX+legW), float64(legY+legH), legendBG)
	for i, e := range entries {
		baseline := legY + 16 + i*14
		drawText(img, legX+5, baseline, e.text, textColor)
		sx := legX + 5 + measureText(e.text) + 5
		drawLine(img, float64(sx), float64(baseline-4), float64(sx+20), float64(baseline-4), 2, e.col)
	}
}

func drawTag(img *image.NRGBA, px, py float64, text string, col color.NRGBA, imgW, offY, chartH int) {
	tw := measureText(text)
	bodyW := tw + 14
	bodyH := 16
	bodyX := int(px) + 10
	if bodyX+bodyW > imgW-1 {
		bodyX = imgW - 1 - bodyW
	}
	if bodyX < int(px)+3 {
		bodyX = int(px) + 3
	}
	bodyY := int(py) - bodyH/2
	if bodyY < offY+4 {
		bodyY = offY + 4
	}
	if bodyY+bodyH > offY+chartH-4 {
		bodyY = offY + chartH - 4 - bodyH
	}
	// Pointer triangle (supersampled point-in-triangle).
	tri := [][2]float64{{px, py}, {float64(bodyX), float64(bodyY + 3)}, {float64(bodyX), float64(bodyY + bodyH - 3)}}
	fillTriangle(img, tri, col)
	// Body: rounded rect approximated by rect + corner clipping.
	for y := bodyY; y < bodyY+bodyH; y++ {
		for x := bodyX; x < bodyX+bodyW; x++ {
			// Rounded corners radius 3.
			dx, dy := 0, 0
			if x < bodyX+3 {
				dx = bodyX + 3 - x
			} else if x > bodyX+bodyW-4 {
				dx = x - (bodyX + bodyW - 4)
			}
			if y < bodyY+3 {
				dy = bodyY + 3 - y
			} else if y > bodyY+bodyH-4 {
				dy = y - (bodyY + bodyH - 4)
			}
			if dx > 0 && dy > 0 && dx*dx+dy*dy > 12 {
				continue
			}
			blendPixel(img, x, y, col, 1)
		}
	}
	drawText(img, bodyX+(bodyW-tw)/2, bodyY+12, text, whiteColor)
}

func fillTriangle(img *image.NRGBA, tri [][2]float64, col color.NRGBA) {
	minx := int(math.Floor(math.Min(tri[0][0], math.Min(tri[1][0], tri[2][0]))))
	maxx := int(math.Ceil(math.Max(tri[0][0], math.Max(tri[1][0], tri[2][0]))))
	miny := int(math.Floor(math.Min(tri[0][1], math.Min(tri[1][1], tri[2][1]))))
	maxy := int(math.Ceil(math.Max(tri[0][1], math.Max(tri[1][1], tri[2][1]))))
	sign := func(a, b, c [2]float64) float64 {
		return (a[0]-c[0])*(b[1]-c[1]) - (b[0]-c[0])*(a[1]-c[1])
	}
	for y := miny; y <= maxy; y++ {
		for x := minx; x <= maxx; x++ {
			cnt := 0
			for sy := 0; sy < 2; sy++ {
				for sx := 0; sx < 2; sx++ {
					p := [2]float64{float64(x) + (float64(sx)+0.5)/2, float64(y) + (float64(sy)+0.5)/2}
					d1 := sign(p, tri[0], tri[1])
					d2 := sign(p, tri[1], tri[2])
					d3 := sign(p, tri[2], tri[0])
					hasNeg := d1 < 0 || d2 < 0 || d3 < 0
					hasPos := d1 > 0 || d2 > 0 || d3 > 0
					if !(hasNeg && hasPos) {
						cnt++
					}
				}
			}
			if cnt > 0 {
				blendPixel(img, x, y, col, float64(cnt)/4)
			}
		}
	}
}
