package main

import (
	"fmt"
	"image"
	"io"
	"sort"
)

// Minimal Sixel encoder. Pixels are composited over black for colour
// purposes (sixel has no per-pixel alpha beyond "no dot"), then
// colour-quantised to at most 254 palette entries by median cut.

type rgb struct{ r, g, b uint8 }

func premul(p []uint8) (rgb, bool) {
	a := int(p[3])
	if a == 0 {
		return rgb{}, false
	}
	return rgb{uint8(int(p[0]) * a / 255), uint8(int(p[1]) * a / 255), uint8(int(p[2]) * a / 255)}, true
}

type colorBox struct {
	colors []rgb
	counts []int
}

func medianCut(hist map[rgb]int, maxColors int) []rgb {
	if len(hist) <= maxColors {
		out := make([]rgb, 0, len(hist))
		for c := range hist {
			out = append(out, c)
		}
		sortColors(out)
		return out
	}
	var cs []rgb
	var ns []int
	for c, n := range hist {
		cs = append(cs, c)
		ns = append(ns, n)
	}
	boxes := []colorBox{{cs, ns}}
	for len(boxes) < maxColors {
		// Pick the box with the largest channel range * count.
		best := -1
		bestScore := -1
		for i, b := range boxes {
			if len(b.colors) < 2 {
				continue
			}
			minr, ming, minb := 255, 255, 255
			maxr, maxg, maxb := 0, 0, 0
			total := 0
			for j, c := range b.colors {
				if int(c.r) < minr { minr = int(c.r) }
				if int(c.g) < ming { ming = int(c.g) }
				if int(c.b) < minb { minb = int(c.b) }
				if int(c.r) > maxr { maxr = int(c.r) }
				if int(c.g) > maxg { maxg = int(c.g) }
				if int(c.b) > maxb { maxb = int(c.b) }
				total += b.counts[j]
			}
			rng := max3(maxr-minr, maxg-ming, maxb-minb)
			if score := rng * total; score > bestScore {
				bestScore = score
				best = i
			}
		}
		if best < 0 {
			break
		}
		b := boxes[best]
		// Channel with largest range.
		minr, ming, minb := 255, 255, 255
		maxr, maxg, maxb := 0, 0, 0
		for _, c := range b.colors {
			if int(c.r) < minr { minr = int(c.r) }
			if int(c.g) < ming { ming = int(c.g) }
			if int(c.b) < minb { minb = int(c.b) }
			if int(c.r) > maxr { maxr = int(c.r) }
			if int(c.g) > maxg { maxg = int(c.g) }
			if int(c.b) > maxb { maxb = int(c.b) }
		}
		ch := 0
		if maxg-ming > maxr-minr && maxg-ming >= maxb-minb {
			ch = 1
		} else if maxb-minb > maxr-minr {
			ch = 2
		}
		idx := make([]int, len(b.colors))
		for i := range idx { idx[i] = i }
		sort.Slice(idx, func(a, b2 int) bool {
			return chVal(b.colors[idx[a]], ch) < chVal(b.colors[idx[b2]], ch)
		})
		total := 0
		for _, n := range b.counts { total += n }
		acc := 0
		split := 0
		for k, id := range idx {
			acc += b.counts[id]
			if acc >= total/2 {
				split = k + 1
				break
			}
		}
		if split <= 0 { split = 1 }
		if split >= len(idx) { split = len(idx) - 1 }
		var b1, b2 colorBox
		for k, id := range idx {
			if k < split {
				b1.colors = append(b1.colors, b.colors[id]); b1.counts = append(b1.counts, b.counts[id])
			} else {
				b2.colors = append(b2.colors, b.colors[id]); b2.counts = append(b2.counts, b.counts[id])
			}
		}
		boxes = append(boxes[:best], append([]colorBox{b1, b2}, boxes[best+1:]...)...)
	}
	out := make([]rgb, 0, len(boxes))
	for _, b := range boxes {
		var sr, sg, sb, tot int
		for j, c := range b.colors {
			n := b.counts[j]
			sr += int(c.r) * n; sg += int(c.g) * n; sb += int(c.b) * n; tot += n
		}
		if tot == 0 { continue }
		out = append(out, rgb{uint8(sr / tot), uint8(sg / tot), uint8(sb / tot)})
	}
	sortColors(out)
	return out
}

func max3(a, b, c int) int {
	if a >= b && a >= c { return a }
	if b >= c { return b }
	return c
}
func chVal(c rgb, ch int) int {
	switch ch { case 0: return int(c.r); case 1: return int(c.g); default: return int(c.b) }
}
func sortColors(cs []rgb) {
	sort.Slice(cs, func(i, j int) bool {
		if cs[i].r != cs[j].r { return cs[i].r < cs[j].r }
		if cs[i].g != cs[j].g { return cs[i].g < cs[j].g }
		return cs[i].b < cs[j].b
	})
}

func nearestColor(palette []rgb, c rgb) int {
	best, bestd := 0, 1<<62
	for i, p := range palette {
		dr := int(c.r) - int(p.r); dg := int(c.g) - int(p.g); db := int(c.b) - int(p.b)
		d := dr*dr + dg*dg + db*db
		if d < bestd { best, bestd = i, d }
	}
	return best
}

func encodeSixel(w io.Writer, img *image.NRGBA) error {
	b := img.Bounds()
	width, height := b.Dx(), b.Dy()
	if width <= 0 || height <= 0 {
		// Match PNG encoder error path used by callers for 0 size.
		_, err := fmt.Fprintf(w, "")
		return err
	}
	// Histogram of quantised (5-bit) premultiplied colours.
	hist := map[rgb]int{}
	pixIdx := make([]int, width*height)  // palette index, -1 transparent; filled later
	pixRGB := make([]rgb, width*height)
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			i := img.PixOffset(b.Min.X+x, b.Min.Y+y)
			c, ok := premul(img.Pix[i : i+4])
			pos := y*width + x
			if !ok {
				pixIdx[pos] = -1
				continue
			}
			pixRGB[pos] = c
			q := rgb{c.r & 0xf8, c.g & 0xf8, c.b & 0xf8}
