		for _, n := range b.counts { total += n }
		acc := 0
		split := 0
		for k, id := range idx {
			acc += b.counts[id]
			if acc >= total/2 {
				split = k + 1
				break
			}
		}
		if split <= 0 { split = 1 }
		if split >= len(idx) { split = len(idx) - 1 }
		var b1, b2 colorBox
		for k, id := range idx {
			if k < split {
				b1.colors = append(b1.colors, b.colors[id]); b1.counts = append(b1.counts, b.counts[id])
			} else {
