new='''// ---- points ----

type fieldHistory struct {
	buf  []float64
	next int
	full bool
}

type points struct {
	mu     sync.Mutex
	graphs [][]*fieldSpec
	steps  int

	histories map[*fieldSpec]*fieldHistory
}

func newPoints(graphs [][]*fieldSpec, steps int) *points {
	p := &points{graphs: graphs, steps: steps, histories: make(map[*fieldSpec]*fieldHistory)}
	for _, g := range graphs {
		for _, f := range g {
			p.histories[f] = &fieldHistory{}
		}
	}
	return p
}

func (p *points) appendValue(f *fieldSpec, v float64) {
	h := p.histories[f]
	if p.steps > 0 {
		if len(h.buf) < p.steps {
			h.buf = append(h.buf, v)
		} else {
			h.buf[h.next] = v
			h.next = (h.next + 1) % p.steps
			h.full = true
		}
	} else {
		h.buf = append(h.buf, v)
	}
}

func (p *points) Run(ctx context.Context, src source) error {
	first := true
	for {
		obj, err := src.Get(ctx)
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return err
		}

		p.mu.Lock()
		for _, group := range p.graphs {
