func main(){
 for _,fn:=range os.Args[1:]{f,_:=os.Open(fn);img,_:=png.Decode(f);f.Close();nr:=img.(*image.NRGBA);b:=img.Bounds();get:=func(x,y int)[]uint8{i:=nr.PixOffset(x,y);return nr.Pix[i:i+4]}
 // axis right first col with count >3/4
