 sort.Slice(bands,func(i,j int)bool{return bands[i].y0<bands[j].y0})
 fmt.Printf("%s axis=%d margin=%d bands=",fn,axis,b.Dx()-axis)
 for _,bd:=range bands{fmt.Printf("y%d:x%d-%d(w%d) ",bd.y0,bd.minx,bd.maxx,bd.maxx-bd.minx+1)}
 fmt.Println()
 }
}
