s=open('graph.go').read()
start=s.index('\t// Series fills and lines.')
end=s.index('\t// Marker vertical dashed lines.')
new='''\t// Series fills and lines. The fill goes to the zero line
	// (clamped to the sub-chart at the top and to the plot
	// bottom), matching the reference for negative series.
	yZero := yFor(0)
	for _, sd := range series {
		fill := sd.color
		fill.A = 20
		x0i := int(math.Ceil(xFor(0))) + 1
		x1i := int(math.Floor(xFor(steps-1))) - 2
		for x := x0i; x <= x1i; x++ {
			fx := (float64(x) - plotLeft) / (plotRight - plotLeft) * float64(steps-1)
			idx := int(math.Floor(fx))
			if idx < 0 {
				idx = 0
			}
			if idx >= steps-1 {
				idx = steps - 2
			}
			frac := fx - float64(idx)
			if frac < 0 {
				frac = 0
			} else if frac > 1 {
				frac = 1
			}
			v := sd.vals[idx]*(1-frac) + sd.vals[idx+1]*frac
			yt := yFor(v)
			if !finite(yt) {
				continue
			}
			lo := math.Min(yt, yZero)
			hi := math.Max(yt, yZero)
			if lo < float64(offY) {
				lo = float64(offY)
			}
			if hi > plotBottomF {
				hi = plotBottomF
			}
			for y := int(math.Floor(lo)); y < int(math.Ceil(hi)); y++ {
				cov := math.Min(hi, float64(y+1)) - math.Max(lo, float64(y))
				if cov > 0 {
					blendPixel(img, x, y, fill, cov)
				}
			}
		}
		for i := 0; i < steps-1; i++ {
			drawLine(img, xFor(i), yFor(sd.vals[i]), xFor(i+1), yFor(sd.vals[i+1]), 2, sd.color)
		}
	}

'''
s=s[:start]+new+s[end:]
open('graph.go','w').write(s)
